from typing import List, Optional

from taf.rfrl.csv4all.resources.node.node import Node
from taf.rfrl.csv4all.resources.test_cases import NetactFeatureTest, UpgradeTest
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.test_global_constants import KPI_PER_TEST_CASE
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class NetactSiteResetTest(NetactFeatureTest):
    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 netact_dict: dict, report: bool, calculate_kpi: Optional[bool] = True,
                 kpi_targets: Optional[dict] = None, use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None,
                 qc_id: Optional[str] = None, qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 stop_test_after_fail: bool = False, l3_call_method: Optional[callable] = None,
                 deintegrate_after_test: bool = True, integrate_before_test: bool = True,
                 reset_without_ru: Optional[bool] = None,
                 graceful_cell_shutdown: Optional[bool] = None, detailed_console_log: bool = True,
                 swconfig_modification: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details=nodes_details, test_nodes_details=test_nodes_details,
                         iterations_per_node=iterations_per_node, netact_dict=netact_dict, report=report,
                         calculate_kpi=calculate_kpi, kpi_targets=kpi_targets,
                         use_dcap=use_dcap, qc_domain=qc_domain, qc_id=qc_id, qc_project=qc_project,
                         customers_list=customers_list, report_comment=report_comment, sw_build=sw_build,
                         topology=topology, stop_test_after_fail=stop_test_after_fail,
                         deintegrate_after_test=deintegrate_after_test, integrate_before_test=integrate_before_test,
                         l3_call_method=l3_call_method, detailed_console_log=detailed_console_log,
                         collect_passed_logs=collect_passed_logs)
        self.reset_without_ru = reset_without_ru
        self.graceful_cell_shutdown = graceful_cell_shutdown
        self.kpi_to_calculate = KPI_PER_TEST_CASE.get("Site Reset")
        self.reset_incrementation = True
        self.uuf_case_type = "reset"
        self.swconfig_modification = swconfig_modification
        self.turn_off_kpi_if_needed()

    def test_setup(self):
        super(UpgradeTest, self).test_setup()
        for node in self.test_nodes:
            self.check_active_sw(node, node.target_sw)
        self.swconfig_precondition(self.swconfig_modification)
        self.setup_netact_and_integrate_nodes()

    def test_operation(self, node):
        if self.report_to_rp:
            self.test_reporter.get_start_time()
        self.add_all_allowed_specific_faults(node)
        node.reset_site(self.reset_without_ru, self.graceful_cell_shutdown)

    def run_iteration_precondition(self):
        super(UpgradeTest, self).run_iteration_precondition()

    def run_iteration_postcondition(self, node):
        super(UpgradeTest, self).run_iteration_postcondition(node)

    def test(self):
        super(UpgradeTest, self).test()

    def run_kpi_calculation(self, node):
        super(UpgradeTest, self).run_kpi_calculation(node)

    def run_test_verification(self, node, hw_timer: int = None, alarm_timer: int = None):
        if node.ru_manager:
            node.execute_commands_on_rmods()
        failed_nodes = self.multi_runner.verify_all_nodes(hw_timer, alarm_timer)
        failed_nodes.update(self.multi_runner.stop_logs_and_verify_on_all_nodes(self.current_logs_dir, node,
                                                                                self.reset_incrementation))
        failed_nodes.update(self.check_connection_with_netact(node))
        failed_nodes.update(self.verify_cells_via_netact(node))
        if not failed_nodes and not self.passed_logs_gathered:
            self.gather_mumin_logs_and_snapshot()
        if self.report_to_rp:
            self.test_reporter.get_end_time()
        if failed_nodes:
            self.gather_mumin_logs_and_snapshot()
            test_logger(f"[{node.node_alias}] SITE RESET FAILED", "error")
        else:
            test_logger(f"[{node.node_alias}] SITE RESET PASSED", hyperlink=True)
        return failed_nodes

    @method_decorator()
    def check_connection_with_netact(self, node, cm_provision=None):
        try:
            node.check_connection_to_netact()
            return set()
        except Exception as e:
            test_logger("Connection with Netact failed, please investigate", "ERROR")
            test_logger(e, "DEBUG")
            return {node.node_alias}

    def test_teardown(self):
        self.current_logs_dir = f"{self.log_dir}/Test_Teardown"
        try:
            if self.deintegrate_after_test:
                for node in self.test_nodes:
                    try:
                        node.deintegrate_mrbts()
                    except Exception:
                        test_logger("Deintegration failed", "error")
            self.teardown_netact()
        finally:
            super()._common_test_teardown()
            if self.swconfig_modification:
                self.multi_runner.run_operations_in_sequence(self.test_nodes, Node.restore_swconfig)

    def turn_off_kpi_if_needed(self):
        if self.reset_without_ru:
            test_logger("Calculating KPI will be disabled, parameter reset_without_ru is set on True")
            self.calculate_kpi = False
